import com.bankScraper.common.EncryptDecrypt
import org.bson.types.ObjectId

class Document {

    static mapWith = "mongo"
    static auditable = [ignoreEvents: ["onSave"]]

    ObjectId id
    String name
    String originalName
    String path
    String contentType
    Date dateCreated
    Date lastUpdated
    String uniqueId = AppUtil.uniqueStr
    String password
    Enums.StaticFileStorageTarget staticFileStorageTarget = Enums.StaticFileStorageTarget.AZURE

    static constraints = {
        name blank: false, nullable: false
        path blank: false, nullable: false
        contentType blank: false, nullable: false
        password blank: true, nullable: true
        originalName blank: true, nullable: true
        staticFileStorageTarget blank: true, nullable: true
    }

    static transients = ['decryptedPassword', 'displayName']

    def beforeInsert() {
        this.password =<REDACTED>
    }

    Document() {}

    Document(ProcessBankStatementCO bankStatementCO) {
        Date currentDate = new Date()
        String filePath = AppUtil.staticResourcesDirPath + "/Success_Files/Client_${bankStatementCO?.client?.id}/${currentDate.format("dd-MMM-yyyy")}/${bankStatementCO?.bank}/${bankStatementCO.contentType?.replaceAll("/", "-")}/"
        this.name = bankStatementCO.bankStatement.name
        this.originalName = bankStatementCO.fileName
        this.contentType = bankStatementCO.contentType
        this.password =<REDACTED>
        String uniqueId = AppUtil.uniqueStr
        this.path = filePath + "${uniqueId}_${bankStatementCO.bankStatement.name}"
        this.uniqueId = uniqueId
        HelperMethod.uploadObjectToLocalOrAzure(bankStatementCO.bankStatement, "${this.path}")
    }

    Document(FailedStatementVO failedStatementVO) {
        Date currentDate = new Date()
        ProcessBankStatementCO bankStatementCO = failedStatementVO.processBankStatementCO
        String filePath = AppUtil.staticResourcesDirPath + "/Failed_Files/Client_${bankStatementCO?.client?.id}/${currentDate.format("dd-MMM-yyyy")}/${bankStatementCO?.bank}/${bankStatementCO.contentType?.replaceAll("/", "-")}/"
        this.name = bankStatementCO.bankStatement.name
        this.originalName = failedStatementVO.fileName
        this.contentType = bankStatementCO.contentType
        this.password =<REDACTED>
        String uniqueId = AppUtil.uniqueStr
        this.path = filePath + "${uniqueId}_${bankStatementCO.bankStatement.name}"
        this.uniqueId = uniqueId
//        HelperMethod.uploadObjectToLocalOrS3(bankStatementCO.bankStatement.bytes, "${this.path}") //TODO : Use Azure
        HelperMethod.uploadObjectToLocalOrAzure(bankStatementCO.bankStatement, "${this.path}") //TODO : Used Azure
    }

    String getDecryptedPassword() {
        EncryptDecrypt.decrypt(this.password)
    }

    String getDisplayName() {
        this.originalName ?: this.name
    }
}
