public static InputStream downloadObjectFromLocalOrS3OrAzure(com.bankScraper.bank.Document document) {
    InputStream inputStream = null
    if (document) {
        File file = FileUtils.getFile(document.path)
        if (file.exists()) {
            log.info("=== Requesting file for download from Local location ===>>> ${document.path}")
            inputStream = file.newDataInputStream()
        } else if (document.staticFileStorageTarget == Enums.StaticFileStorageTarget.AZURE) {
            log.info("=== Requesting file for download from Azure location ===>>> ${document.path}")
            inputStream = downloadObjectFromAzure(document.path)
        } else if (document.staticFileStorageTarget == Enums.StaticFileStorageTarget.GOOGLE) {
            log.info("=== Requesting file for download from Google Cloud Storage location ===>>> ${document.path}")
            inputStream = downloadObjectFromGoogleCloudStorage(document.path)
        } else {
            log.info("=== Requesting file for download from S3 location ===>>> ${document.path}")
            inputStream = downloadObjectFromS3(document.path)
        }
    }
    inputStream
}

