/**
 * Name of the classpath resource holding the Google service account key of the deployed environment.
 * The resource is optional, when it is not available the ambient(default) credentials of the runtime are used.
 */
public static final String GOOGLE_SERVICE_ACCOUNT_RESOURCE = "google-cloud-storage-service-account.json"

private static String fetchConfigValue(List<String> configKeys) {
    String configValue = null
    try {
        def flatConfig = Holders.getFlatConfig()
        configValue = configKeys.findResult { String key ->
            def value = flatConfig?.get(key)
            value && StringUtils.isNotBlank("${value}") ? "${value}" : null
        }
    }
    catch (Exception e) {
        log.error("Exception while reading configuration ${configKeys} ==>> ${e.message}", e)
    }
    configValue
}

private static String fetchGoogleCloudStorageBucketName() {
    fetchConfigValue(["google.storage.bucket.name", "google.bucket.name", "grails.google.storage.bucket.name",
                      "grails.s3.bucket.name"])
}

private static InputStream fetchGoogleServiceAccountStream() {
    InputStream credentialStream = null
    try {
