/**
 * Ways of obtaining the configured Google {@link Storage} service, in order of preference. The service account
 * resource of the deployed runtime is optional, when it is absent the ambient(default) credentials are used.
 */
private static List<Closure<Storage>> googleCloudStorageServiceProviders() {
    [
            { -> fetchGoogleCloudStorageServiceUsingServiceAccount() },
            { -> StorageOptions.newBuilder().build().getService() },
            { -> StorageOptions.getDefaultInstance().getService() }
    ]
}

/**
 * Runs the given operation against the configured Google {@link Storage} service, the first service which is able
 * to serve the operation wins.
 */
private static def withGoogleCloudStorage(Closure operation) {
    def result = null
    googleCloudStorageServiceProviders().find { Closure<Storage> serviceProvider ->
        Storage storage = null
        try {
            storage = serviceProvider.call()
        }
        catch (Exception e) {
            log.error("Exception while building Google Cloud Storage service ==>> ${e.message}", e)
        }
        if (storage == null)
            return false
        try {
            result = operation.call(storage)
        }
        catch (Exception e) {
            log.error("Exception while accessing Google Cloud Storage ==>> ${e.message}", e)
        }
        result != null
    }
    result
}

